// Generated embedded base64 zip bundles for client-side instant file saving
function downloadBase64(base64Data: string, filename: string) {
  const byteChars = atob(base64Data);
  const byteNumbers = new Array(byteChars.length);
  for (let i = 0; i < byteChars.length; i++) {
    byteNumbers[i] = byteChars.charCodeAt(i);
  }
  const byteArray = new Uint8Array(byteNumbers);
  const blob = new Blob([byteArray], { type: 'application/zip' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

const DIST_ZIP_B64 = "";
const SRC_ZIP_B64 = "";

export function downloadDistZip() {
  downloadBase64(DIST_ZIP_B64, 'senku-dist.zip');
}

export function downloadSourceZip() {
  downloadBase64(SRC_ZIP_B64, 'senku-full-project.zip');
}
